      SUBROUTINE ORDCKCC     CHECKS TO MAKE SURE THAT ORDER OF PROGRAM USED IS AT LEASTC     AS GREAT AS ORDER OF CALCULATION REQUESTEDCC     LIST OF COMMON BLOCKSC      INCLUDE 'ELM17A.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'IOUNIT.CIN'CC-------------------------------------------------------------------      IF (NORDX .GT. 3) THEN        WRITE (NOUT,1000) NORDX 1000   FORMAT (' *** ERROR *** ORDER',I3,2X,'SPECIFIED FOR',     1          ' THIRD-ORDER PROGRAM')        FLUSHL = .TRUE.      ENDIF      RETURN      END